Aqui está a solução completa, estruturada segundo as etapas heurísticas de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA
- **Objetivo Central:** Encontrar o número máximo de salas em um ciclo formado pela adição de uma única nova aresta (túnel) a uma árvore dada, e contar quantas maneiras distintas existem de criar esse ciclo máximo.
- **Definição de Ciclo Máximo:** Ao adicionar uma aresta entre dois vértices $u$ e $v$, o ciclo formado consiste no caminho simples entre eles mais a nova aresta. O número de vértices no ciclo é $\text{dist}(u, v) + 1$. Logo, maximizar o ciclo equivale a maximizar $\text{dist}(u, v)$, que é o **diâmetro** $D$ da árvore. O ciclo máximo terá comprimento $D + 1$.
- **Contagem:** Precisamos contar quantos pares não-ordenados $\{u, v\}$ têm distância igual ao diâmetro $D$.
- **Limites e Tipos:**
  - $3 \le N \le 50000$.
  - O número de pares é $< 10^8$ (cabe em tipos inteiros usuais, mas usaremos `long long` para evitar qualquer overflow durante os produtos).
- **Casos de borda:**
  - Diâmetro par (centro único).
  - Diâmetro ímpar (dois centros conectados por uma aresta central).

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO
Propriedade clássica de árvores:
> **Todo caminho diametral (comprimento $D$) contém o centro da árvore.**
> - Se $D$ é par, há um único centro $c$. Todos os caminhos diametrais têm $c$ como ponto médio, com as extremidades a uma distância exatamente $D / 2$ de $c$, pertencentes a ramos (subárvores dos vizinhos de $c$) distintos.
> - Se $D$ é ímpar, há dois centros $c_1$ e $c_2$ conectados por uma aresta. Todo caminho diametral passa pela aresta $(c_1, c_2)$, tendo uma ponta na componente de $c_1$ a distância $(D-1)/2$ e a outra ponta na componente de $c_2$ a distância $(D-1)/2$.

**Passo a passo da estratégia:**
1. Usar duas buscas em largura (BFS):
   - BFS a partir de um vértice arbitrário (ex: 1) para encontrar um vértice mais distante $A$.
   - BFS a partir de $A$ para encontrar o vértice mais distante $B$, guardando os predecessores (`parent`) para reconstruir o caminho diametral de $A$ até $B$.
2. O comprimento do caminho é $D$ (número de arestas). O comprimento máximo do ciclo é $D + 1$.
3. Identificar os centros pelo caminho de $A$ até $B$:
   - Se $D$ for par, o centro é $c = \text{caminho}[D/2]$.
     - Para cada vizinho $v$ de $c$, fazemos uma busca (DFS ou BFS) na subárvore de $v$ para contar quantos vértices estão à distância $D / 2$ de $c$.
     - Sejam essas contagens $cnt_1, cnt_2, \dots, cnt_k$. O número de pares é:
       $$\sum_{i < j} cnt_i \times cnt_j = \frac{\left(\sum cnt_i\right)^2 - \sum cnt_i^2}{2}$$
   - Se $D$ for ímpar, os centros são $c_1 = \text{caminho}[(D-1)/2]$ e $c_2 = \text{caminho}[(D+1)/2]$.
     - Contamos os vértices na componente de $c_1$ (sem passar por $c_2$) a distância $(D-1)/2$ de $c_1$ ($cnt_1$).
     - Contamos os vértices na componente de $c_2$ (sem passar por $c_1$) a distância $(D-1)/2$ de $c_2$ ($cnt_2$).
     - O número de pares é $cnt_1 \times cnt_2$.

**Complexidade:**
- **Tempo:** $O(N)$ — 2 BFSs e algumas travessias lineares.
- **Espaço:** $O(N)$ — representação por lista de adjacência estática (Forward Star / Head-To-Next).

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAXN 50005

/* Representação do grafo por lista de adjacência (Forward Star) */
int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], edge_cnt;

static void add_edge(int u, int v) {
    edge_cnt++;
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt;
}

/* Estruturas para BFS */
int dist[MAXN];
int parent_node[MAXN];
int queue[MAXN];

/* Executa BFS a partir de 'src' e retorna o vértice mais distante */
static int bfs(int src, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        parent_node[i] = 0;
    }

    int q_front = 0, q_back = 0;
    queue[q_back++] = src;
    dist[src] = 0;

    int farthest = src;

    while (q_front < q_back) {
        int u = queue[q_front++];
        if (dist[u] > dist[farthest]) {
            farthest = u;
        }

        for (int e = head[u]; e != 0; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent_node[v] = u;
                queue[q_back++] = v;
            }
        }
    }

    return farthest;
}

/* DFS para contar quantos nós estão na profundidade alvo */
static int dfs_count(int u, int p, int d, int target_d) {
    if (d == target_d) {
        return 1;
    }
    int count = 0;
    for (int e = head[u]; e != 0; e = nxt[e]) {
        int v = to[e];
        if (v != p) {
            count += dfs_count(v, u, d + 1, target_d);
        }
    }
    return count;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    edge_cnt = 0;
    for (int i = 1; i <= n; i++) {
        head[i] = 0;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    /* Passo 1: Encontrar um dos extremos de um caminho diametral */
    int nodeA = bfs(1, n);

    /* Passo 2: A partir de nodeA, encontrar o outro extremo nodeB */
    int nodeB = bfs(nodeA, n);

    int diameter = dist[nodeB];

    /* Reconstruir o caminho de nodeB até nodeA */
    static int path[MAXN];
    int curr = nodeB;
    for (int i = diameter; i >= 0; i--) {
        path[i] = curr;
        curr = parent_node[curr];
    }

    long long total_pairs = 0;

    if (diameter % 2 == 0) {
        /* Diâmetro par: Centro único */
        int center = path[diameter / 2];
        int target_depth = diameter / 2;

        long long sum = 0;
        long long sum_sq = 0;

        for (int e = head[center]; e != 0; e = nxt[e]) {
            int v = to[e];
            long long cnt = dfs_count(v, center, 1, target_depth);
            sum += cnt;
            sum_sq += cnt * cnt;
        }

        total_pairs = (sum * sum - sum_sq) / 2;
    } else {
        /* Diâmetro ímpar: Dois centros conectados por uma aresta central */
        int c1 = path[(diameter - 1) / 2];
        int c2 = path[(diameter + 1) / 2];
        int target_depth = (diameter - 1) / 2;

        long long cnt1 = dfs_count(c1, c2, 0, target_depth);
        long long cnt2 = dfs_count(c2, c1, 0, target_depth);

        total_pairs = cnt1 * cnt2;
    }

    /* O comprimento do ciclo é o diâmetro em arestas + 1 */
    printf("%d\n", diameter + 1);
    printf("%lld\n", total_pairs);

    return 0;
}
```

